Given an integer n, determine whether it is a palindrome number or not. A number is called a palindrome if it reads the same from forward and backward.Examples:Input: n = 12321Output: TrueExplanation: 12321 is a palindrome number because it reads same  forward and backward.Input: n = -121Output: TrueExplanation:  We number is palindrome, we mainly ignore sign.Input: n = 1234Output:  FalseExplanation: 1234 is not a palindrome number because it does not read the same forward and backward.Try It YourselfTable of Content[Expected Approach] - By Reversing The Number[Alternate Approach] - Using Number as String [Expected Approach] - By Reversing The NumberThe idea is to find the reverse of the original number and then compare the reversed number with the original number. If the reversed number is same as the original number, the number is palindrome. Otherwise, the number is not a palindrome.  
            C++

    #include <iostream>
using namespace std;

bool isPalindrome(int n) {
    int reverse = 0;

    // Copy of the original number so that the original
    // number remains unchanged while finding the reverse
    int temp = abs(n);
    while (temp != 0) {
        reverse = (reverse * 10) + (temp % 10);
        temp = temp / 10;
    }

    // If reverse is equal to the original number,
    // the number is palindrome
    return (reverse == abs(n));
}

int main() {
    int n = 12321;
    if (isPalindrome(n) == 1) {
        cout << "True";
    }
    else {
        cout << "False";
    }
    return 0;
}


