            C++

    #include <iostream>
using namespace std;

bool isPalindrome(int n) {

    // Convert the absolute value
    // of number to string
    string s = to_string(abs(n));
	int len = s.length();

    for (int i = 0; i < len / 2; i++) {

        // Comparing i th character from starting
        //  and len-i th character from end
        if (s[i] != s[len - i - 1])
            return false;
    }
    return true;
}

